mapper.sql:
WHERE e.is_deleted = FALSE
  AND e.publish_status = 'PUBLISHED'
  AND e.attendance_mode <> 'ONLINE'
  AND e.event_status <> 'MOVED_ONLINE'
  AND e.end_at > #{p.from}
  AND e.start_at < #{p.to}
  AND e.latitude BETWEEN #{p.minLat} AND #{p.maxLat}
  AND e.longitude BETWEEN #{p.minLng} AND #{p.maxLng}
  AND  <= #{p.radiusKm}

  AND e.category IN
    #{category}

WHERE e.is_deleted = FALSE

  AND (e.title_norm LIKE ('%' || #{p.searchNorm} || '%') ESCAPE '\'
       OR e.external_id = #{p.search})


  AND e.publish_status IN
    #{status}


  AND e.event_status IN
    #{status}


  AND e.category IN
    #{category}


  AND e.source = #{p.source}


  AND e.province_code = #{p.provinceCode}


  AND e.start_at >= #{p.startFrom}


  AND e.start_at < #{p.startTo}


  AND e.duplicate_of_event_id IS NOT NULL

mapper.select:
SELECT FROM local_events e
ORDER BY e.start_at DESC, e.id DESC ORDER BY e.start_at ASC, e.id ASC ORDER BY e.created_at DESC, e.id DESC ORDER BY e.created_at ASC, e.id ASC ORDER BY e.updated_at DESC, e.id DESC ORDER BY e.updated_at ASC, e.id ASC
LIMIT #{p.limit} OFFSET #{p.offset}

SELECT 
FROM local_events e
WHERE e.id = #{id}

SELECT 
FROM local_events e
WHERE e.source = #{source}
  AND e.external_id = #{externalId}

SELECT e.id, e.title, e.start_at, e.venue_name,
       similarity(e.title_norm, #{p.titleNorm}) AS score
FROM local_events e
WHERE e.is_deleted = FALSE

  AND e.id <> #{p.excludeId}

  AND e.start_at >= #{p.startFrom}
  AND e.start_at < #{p.startTo}
  AND e.title_norm % #{p.titleNorm}
  AND similarity(e.title_norm, #{p.titleNorm}) >= #{p.minSimilarity}
  AND (
    (e.latitude BETWEEN #{p.minLat} AND #{p.maxLat}
     AND e.longitude BETWEEN #{p.minLng} AND #{p.maxLng}
     AND (6371 * acos(
            LEAST(1.0, GREATEST(-1.0,
                cos(radians(#{p.latitude})) * cos(radians(e.latitude)) *
                cos(radians(e.longitude) - radians(#{p.longitude})) +
                sin(radians(#{p.latitude})) * sin(radians(e.latitude))
            ))
         )) <= #{p.radiusKm})

    OR e.province_code = #{p.provinceCode}

  )
ORDER BY score DESC, e.start_at ASC, e.id ASC
LIMIT #{p.limit}

mapper.update:
UPDATE local_events
SET publish_status = #{publishStatus},
    published_at = COALESCE(published_at, #{publishedAt}),
    updated_by = #{updatedBy},
    data_version = data_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND is_deleted = FALSE
  AND data_version = #{expectedVersion}
